import {escapeHtml as e} from './utils.js?v=0.19.0';
import {ancestry,generations} from './ancestry.js?v=0.19.0';
export function sourceDetails(value){const a=ancestry(value);return a.parents.length?`<details class="idea-ancestry"><summary>From ${a.parents.map(p=>e(p.title||'Untitled idea')).join(' + ')}</summary><p>Source wording at creation. Later parent edits do not rewrite this branch.</p>${a.parents.map(p=>`<section><h3>${e(p.title||'Untitled idea')}</h3>${p.fields.filter(f=>f.text).map(f=>`<div class="ancestry-field"><span>${e(f.label)}</span><p>${e(f.text)}</p></div>`).join('')}</section>`).join('')}</details>`:'';}
export function familyMap(items,{action='develop',attribute='data-action'}={}){
 const nodes=generations(items),levels=Math.max(0,...nodes.map(n=>n.generation))+1;
 return `<p class="ancestry-hint">Follow the parents, then open a branch to develop it. Parked ideas stay in the history. Scroll sideways through generations ↔.</p><div class="ancestry-scroll" tabindex="0" role="region" aria-label="Idea ancestry; scroll through generations"><div class="ancestry-generations" style="--generations:${levels}">${Array.from({length:levels},(_,i)=>`<section class="ancestry-generation"><h3>${i?'Generation '+i:'Starting points'}</h3>${nodes.filter(n=>n.generation===i).map(n=>`<article class="ancestry-node ${n.ancestry?.parked?'parked':''}"><button ${attribute}="${action}" data-id="${e(n.id)}" class="ancestry-open">${e(n.title||'Untitled idea')}</button>${n.ancestry?.parked?'<small>Parked</small>':''}<p>${e(n.mechanism||'Mechanism to develop.')}</p>${n.ancestry?.parents.length?`<div class="ancestry-parents"><span>From</span>${n.ancestry.parents.map(p=>items.some(n=>n.id===p.id)?`<button ${attribute}="${action}" data-id="${e(p.id)}">${e(p.title||'Untitled parent')}</button>`:`<span>${e(p.title||'Earlier source')} · snapshot retained</span>`).join(' + ')}</div>`:''}${n.changed?`<p><b>Changed:</b> ${e(n.changed)}</p>`:''}${n.reason?`<p><b>Because:</b> ${e(n.reason)}</p>`:''}</article>`).join('')}</section>`).join('')}</div></div>`;
}
export function parentChoices(items,defaults=[]){const choices=selected=>items.map(n=>`<option value="${e(n.id)}" ${n.id===selected?'selected':''}>${e(n.title||'Untitled idea')}${n.ancestry?.parked?' · parked':''}</option>`).join('');return `<p>Keep both source snapshots. The new mechanism starts blank so you can decide how the useful parts work together.</p><div class="ancestry-choice"><label>First parent<select name="parent-a">${choices(defaults[0]??items[0]?.id)}</select></label><label>Second parent<select name="parent-b">${choices(defaults[1]??items[1]?.id)}</select></label></div>`;}
